#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_HEADER_LEN 4096
#define MAX_PATH_LEN 2048
#define MAX_QUERY_PARAMS 64
#define MAX_SEGMENTS 128

typedef struct {
    char key[256];
    char value[1024];
} query_param_t;

typedef struct {
    char method[16];
    char path[MAX_PATH_LEN];
    char canonical_uri[MAX_PATH_LEN];
    query_param_t params[MAX_QUERY_PARAMS];
    int param_count;
    char region[64];
    char service[64];
    unsigned char signing_key[32];
} cloud_request_t;

static int hex_digit(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static int is_unreserved(unsigned char c) {
    return isalnum(c) || c == '-' || c == '_' || c == '.' || c == '~';
}

/* URI-decode a percent-encoded string */
static int uri_decode(const char *src, char *dst, size_t dst_len) {
    size_t si = 0, di = 0;
    size_t src_len = strlen(src);

    while (si < src_len && di < dst_len - 1) {
        if (src[si] == '%' && si + 2 < src_len) {
            int h = hex_digit(src[si+1]);
            int l = hex_digit(src[si+2]);
            if (h >= 0 && l >= 0) {
                dst[di++] = (char)((h << 4) | l);
                si += 3;
            } else {
                dst[di++] = src[si++];
            }
        } else {
            dst[di++] = src[si++];
        }
    }
    dst[di] = '\0';
    return (int)di;
}

/* URI-encode for canonical URI per cloud signing spec */
static int uri_encode_path(const char *src, char *dst, size_t dst_len) {
    size_t si = 0, di = 0;
    size_t src_len = strlen(src);

    while (si < src_len && di < dst_len - 4) {
        unsigned char c = (unsigned char)src[si];
        if (is_unreserved(c) || c == '/') {
            dst[di++] = c;
        } else {
            snprintf(&dst[di], 4, "%%%02X", c);
            di += 3;
        }
        si++;
    }
    dst[di] = '\0';
    return (int)di;
}

/* Normalize path: resolve . and .. segments */
static void normalize_path(char *path) {
    char *segments[MAX_SEGMENTS];
    int seg_count = 0;
    char *p = path;
    char result[MAX_PATH_LEN];

    if (*p == '/') p++;

    char *token = strtok(p, "/");
    while (token != NULL) {
        if (strcmp(token, ".") == 0) {
            /* skip */
        } else if (strcmp(token, "..") == 0) {
            if (seg_count > 0) seg_count--;
        } else {
            if (seg_count < MAX_SEGMENTS) {
                segments[seg_count++] = token;
            } else {
                /* too many segments; stop processing to avoid overflow */
                break;
            }
        }
        token = strtok(NULL, "/");
    }

    result[0] = '/';
    result[1] = '\0';
    for (int i = 0; i < seg_count; i++) {
        strncat(result, segments[i], sizeof(result) - strlen(result) - 1);
        if (i < seg_count - 1)
            strncat(result, "/", sizeof(result) - strlen(result) - 1);
    }
    strncpy(path, result, MAX_PATH_LEN - 1);
    path[MAX_PATH_LEN - 1] = '\0';
}

/*
 * Build canonical URI for request signing.
 * The signing process:
 *   1. Decode the raw URI (handle percent-encoding)
 *   2. Normalize the path (resolve . and ..)
 *   3. Re-encode for canonical form
 *
 * Only a single decode pass is performed regardless of environment
 * to prevent encoding bypass attacks via double-encoding.
 */
int build_canonical_uri(cloud_request_t *req) {
    char decoded[MAX_PATH_LEN];
    char normalized[MAX_PATH_LEN];

    /* Single decode pass only - never double-decode */
    uri_decode(req->path, decoded, sizeof(decoded));

    /* Normalize the decoded path */
    strncpy(normalized, decoded, sizeof(normalized) - 1);
    normalized[sizeof(normalized) - 1] = '\0';
    normalize_path(normalized);

    /* Re-encode for canonical form */
    uri_encode_path(normalized, req->canonical_uri, sizeof(req->canonical_uri));

    return 0;
}

/*
 * Validate that the canonical URI doesn't escape the service root.
 * This check ensures path traversal is blocked AFTER canonicalization.
 */
int validate_request_path(cloud_request_t *req) {
    /* Check the canonical_uri for traversal attempts */
    if (strstr(req->canonical_uri, "..") != NULL) {
        return -1; /* reject */
    }

    /* Also check decoded form for traversal */
    char check_decoded[MAX_PATH_LEN];
    uri_decode(req->canonical_uri, check_decoded, sizeof(check_decoded));
    if (strstr(check_decoded, "..") != NULL) {
        return -1;
    }

    /* Verify path starts with / */
    if (req->canonical_uri[0] != '/') {
        return -1;
    }

    return 0; /* path is safe */
}

int process_cloud_request(const char *raw_path) {
    cloud_request_t req;
    memset(&req, 0, sizeof(req));

    strncpy(req.method, "GET", sizeof(req.method) - 1);
    strncpy(req.path, raw_path, sizeof(req.path) - 1);
    req.path[sizeof(req.path) - 1] = '\0';

    /* Build canonical URI (decode -> normalize -> re-encode) */
    if (build_canonical_uri(&req) != 0) {
        return -1;
    }

    /* Validate the canonical path */
    if (validate_request_path(&req) != 0) {
        fprintf(stderr, "Path validation failed: %s\n", req.canonical_uri);
        return -1;
    }

    printf("Canonical URI: %s\n", req.canonical_uri);
    /* ... proceed with signing and dispatch ... */
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <path>\n", argv[0]);
        return 1;
    }
    return process_cloud_request(argv[1]);
}
